async function get(u) {
  const r = await fetch(u, { headers: { "User-Agent": "Mozilla/5.0" } });
  return { status: r.status, text: await r.text() };
}
const base = "https://raw.githubusercontent.com/";
const targets = {
  universal: base + "Wjavan/AI-Subtitle-Translation/main/SubtitleTranslate%20-%20Universal.as",
  universalReadme: base + "Wjavan/AI-Subtitle-Translation/main/README.md",
  rtl: base + "itszux/PotPlayer-RTL-Extension/main/README.md",
};
const res = {};
for (const [k, u] of Object.entries(targets)) {
  try { const r = await get(u); res[k] = r; } catch (e) { res[k] = { error: String(e) }; }
}
const uas = res.universal.text || "";
const hosts = [...new Set((uas.match(/Host[A-Za-z0-9_]+/g) || []))].sort();
const funcs = [...new Set((uas.match(/^\s*(?:string|void|int|bool|array<string>|uint|double)\s+([A-Za-z_][A-Za-z0-9_]*)\s*\(/gm) || []))].map(s => s.trim());
return {
  universalLen: uas.length,
  hostFns: hosts,
  topLevelFns: funcs,
  readmePreview: (res.universalReadme.text || "").slice(0, 4000),
  rtl: (res.rtl.text || res.rtl.error || "").slice(0, 2000),
};

const r = await fetch("https://raw.githubusercontent.com/Wjavan/AI-Subtitle-Translation/main/SubtitleTranslate%20-%20Universal.as", { headers: { "User-Agent": "Mozilla/5.0" } });
