// ============================== 配置文件 ==============================

string ReadTextFile(const string &in path)
{
    uintptr fp = HostFileOpen(path);
    if (fp == 0) return "";
    int64 len = HostFileLength(fp);
    string data = "";
    if (len > 0) data = HostFileRead(fp, int(len));
    HostFileClose(fp);
    // 去掉 UTF-8 BOM
    if (data.length() >= 3 && data[0] == 0xEF && data[1] == 0xBB && data[2] == 0xBF)
        data = data.substr(3);
    return data;
}

