$text = [System.IO.File]::ReadAllText($path, [System.Text.Encoding]::UTF8)
# 1) 写回 UTF-8 with BOM（与官方扩展一致）
[System.IO.File]::WriteAllText($path, $text, (New-Object System.Text.UTF8Encoding($true)))
# 2) 粗略语法检查：去掉注释和字符串字面量后统计括号
$sb = New-Object System.Text.StringBuilder
$i = 0; $n = $text.Length
while ($i -lt $n) {
  $c = $text[$i]
  if ($c -eq '/' -and $i+1 -lt $n -and $text[$i+1] -eq '/') { while ($i -lt $n -and $text[$i] -ne "`n") { $i++ }; continue }
  if ($c -eq '/' -and $i+1 -lt $n -and $text[$i+1] -eq '*') { $i += 2; while ($i+1 -lt $n -and -not ($text[$i] -eq '*' -and $text[$i+1] -eq '/')) { $i++ }; $i += 2; continue }
  if ($c -eq '"') { $i++; while ($i -lt $n -and $text[$i] -ne '"') { if ($text[$i] -eq '\') { $i++ }; $i++ }; $i++; [void]$sb.Append('S'); continue }
  [void]$sb.Append($c); $i++
}
$code = $sb.ToString()
$lines = $code -split "`n"
$bal = 0; $par = 0; $sq = 0; $issues = @()
for ($k = 0; $k -lt $lines.Count; $k++) {
  foreach ($ch in $lines[$k].ToCharArray()) {
    switch ($ch) { '{' { $bal++ } '}' { $bal-- } '(' { $par++ } ')' { $par-- } '[' { $sq++ } ']' { $sq-- } }
  }
}
"braces={0} parens={1} brackets={2}  (0 = 平衡)" -f $bal, $par, $sq
"总行数: " + ($text -split "`n").Count
"BOM: " + ([System.IO.File]::ReadAllBytes($path)[0..2] -join ',')
"非 ASCII 行数: " + (($text -split "`n") | Where-Object { $_ -match '[\u4e00-\u9fff]' }).Count

