$raw = [System.IO.File]::ReadAllText($p, [System.Text.Encoding]::UTF8)
$nl = "`r`n"
if ($raw -notmatch "`r`n") { $nl = "`n" }
$hadBom = $raw.Length -gt 0 -and [int][char]$raw[0] -eq 0xFEFF
if ($hadBom) { $raw = $raw.Substring(1) }
$lines = [System.Collections.Generic.List[string]]($raw -split "`r?`n")

$startIdx = -1; $langIdx = -1; $engIdx = -1
for ($i = 0; $i -lt $lines.Count; $i++) {
    if ($startIdx -lt 0 -and $lines[$i].StartsWith('// ============================== 内置默认值')) { $startIdx = $i }
    if ($langIdx -lt 0 -and $lines[$i].StartsWith('// ============================== 支持的语言')) { $langIdx = $i }
    if ($engIdx -lt 0 -and $lines[$i].StartsWith('// ============================== 引擎信息')) { $engIdx = $i }
}
"startIdx=$startIdx langIdx=$langIdx engIdx=$engIdx"
if ($startIdx -lt 0 -or $langIdx -lt 0 -or $engIdx -lt 0) { throw "marker not found" }

$block = $lines[$startIdx..($langIdx - 1)]
# drop trailing blank lines from block
while ($block.Count -gt 0 -and $block[$block.Count-1].Trim() -eq '') { $block = $block[0..($block.Count-2)] }
"block lines: $($block.Count)  first='$($block[0])'  last='$($block[$block.Count-1])'"

# remove block + trailing blank line before lang section
$removeEnd = $langIdx - 1
while ($removeEnd -ge $startIdx -and $lines[$removeEnd].Trim() -eq '') { $removeEnd-- }
$lines.RemoveRange($startIdx, ($removeEnd - $startIdx + 1))

# recompute engine index after removal
for ($i = 0; $i -lt $lines.Count; $i++) { if ($lines[$i].StartsWith('// ============================== 引擎信息')) { $engIdx = $i; break } }

$insert = New-Object System.Collections.Generic.List[string]
$insert.AddRange([string[]]$block)
$insert.Add('')
$lines.InsertRange($engIdx, $insert)

$out = ($lines -join $nl)
if ($hadBom) { $out = [char]0xFEFF + $out }
[System.IO.File]::WriteAllText($p, $out, (New-Object System.Text.UTF8Encoding($false)))
"written"

$b = [System.IO.File]::ReadAllBytes($p)
"HasBOM: $(($b[0] -eq 0xEF) -and ($b[1] -eq 0xBB) -and ($b[2] -eq 0xBF))  Size: $($b.Length)"

