```
string ToLowerStr(const string &in s)
{
    string o = s;
    o.resize(s.length());
    for (uint i = 0; i < s.length(); i++)
    {
        uint8 c = s[i];
        if (c >= 0x41 && c <= 0x5A) c = uint8(c + 0x20);
