// 去掉首尾空白（自行实现，避免依赖 Trim() 在不同版本里的返回语义）
string StrTrim(const string &in s)
{
    uint i = 0;
    uint j = s.length();
    while (i < j && IsSpaceByte(s[i])) i++;
    while (j > i && IsSpaceByte(s[j - 1])) j--;
    if (i == 0 && j == s.length()) return s;
    return s.substr(i, int(j - i));
}

