string ToLowerStr(const string &in s)
{
    string o = s;
    for (uint i = 0; i < o.length(); i++)
    {
        uint8 c = o[i];
        if (c >= 0x41 && c <= 0x5A) o[i] = uint8(c + 0x20);
    }
    return o;
}

